// 1. Kiểm tra mã trạng thái trả về (201 Created hoặc 200 OK tùy cấu hình Backend)
pm.test("Đăng ký tài khoản thành công", function () {
    pm.expect(pm.response.code).to.be.oneOf([200, 201]);
});

// 2. Tự động trích xuất token ngay sau khi đăng ký thành công
var jsonData = pm.response.json();
if (jsonData.user && jsonData.user.token) {
    pm.environment.set("token", jsonData.user.token);
    pm.environment.set("registered_username", jsonData.user.username);
    console.log("✨ Đăng ký thành công tài khoản: [" + jsonData.user.username + "] và đã lưu token vào môi trường!");
}

// In toàn bộ cấu hình response ra console để check cho chắc
const res = pm.response.json();
console.log("Response đầy đủ là:", res);

// Bóc tách token linh hoạt theo mọi cấu trúc có thể có của RealWorld App
const token = res.user?.token || res.token || res.access_token;

if (token) {
    pm.environment.set("token_a", token);
    console.log("🔥 Đã bắt và lưu token thành công: " + token.substring(0, 15) + "...");
} else {
    console.error("❌ Vẫn không thấy token, cấu trúc JSON trả về đang là:", JSON.stringify(res));
}

// 1. Kiểm tra mã phản hồi tạo bài viết thành công là 201 Created (hoặc 200 OK)
pm.test("Tạo bài viết thành công", function () {
    pm.expect(pm.response.code).to.be.oneOf([200, 201]);
});

// 2. Bóc tách dữ liệu JSON từ Server trả về
var jsonData = pm.response.json();

// 3. Tự động bóc tách slug và lưu vào biến môi trường (Có cơ chế bảo vệ an toàn)
if (jsonData.article && jsonData.article.slug) {
    var articleSlug = jsonData.article.slug;
    
    // Lưu vào biến môi trường
    pm.environment.set("slug", articleSlug);
    
    // In log ra Console để dễ debug
    console.log("🔥 Đã bắt được Slug bài viết: " + articleSlug);
    
    // Test case xác nhận đã bắt được biến
    pm.test("🚀 Lưu Slug bài viết vào môi trường thành công", function () {
        pm.expect(articleSlug).to.not.be.empty;
    });
} else {
    console.log("❌ Không tìm thấy slug trong response. Vui lòng kiểm tra lại body trả về!");
}

