    pm.response.to.have.status(200);
});

var jsonData = pm.response.json();

// 2. Kiểm tra cấu trúc trả về phải có mảng 'comments'
pm.test("Dữ liệu trả về phải chứa mảng 'comments'", function () {
    pm.expect(jsonData).to.have.property('comments');
    pm.expect(jsonData.comments).to.be.an('array');
});

// 3. Hiển thị danh sách ra Console và kiểm tra chéo
if (jsonData.comments && jsonData.comments.length > 0) {
    // In danh sách ra Postman Console để huynh dễ nhìn
    console.log("🔥 Đã lấy được " + jsonData.comments.length + " bình luận!");
    console.log("Chi tiết danh sách:", jsonData.comments);

    // Kịch bản Pro cho đồ án: Kiểm tra xem cái comment số 7 vừa tạo có nằm trong danh sách này không
    var expectedCommentId = pm.environment.get("comment_id");
    if (expectedCommentId) {
        pm.test("Bình luận vừa tạo (ID: " + expectedCommentId + ") phải tồn tại trong danh sách", function () {
            var found = jsonData.comments.find(c => c.id == expectedCommentId);
            pm.expect(found).to.not.be.undefined;
        });
    }
} else {
    console.log("⚠️ API gọi thành công nhưng danh sách bình luận đang trống trơn!");
}

